"""Compile the wrappers generated by preview-corpus.test.ts without modifying source fixtures."""
import argparse
import concurrent.futures
import hashlib
import json
from pathlib import Path
import subprocess

parser = argparse.ArgumentParser()
parser.add_argument('--input', default='test-results/corpus-drawings.json')
parser.add_argument('--output', required=True)
parser.add_argument('--workers', type=int, default=3, choices=range(1, 5))
args = parser.parse_args()
items = json.loads(Path(args.input).read_text())
output = Path(args.output).resolve()
output.mkdir(parents=True, exist_ok=True)
engine = subprocess.run(['xelatex', '--version'], capture_output=True, text=True, check=True).stdout.splitlines()[0]

def compile_one(entry):
    index, item = entry
    folder = output / f'{index:03d}'
    folder.mkdir(exist_ok=True)
    digest = hashlib.sha256((item['document'] + '\0' + item['question'] + '\0' + engine).encode()).hexdigest()
    old = folder / 'result.json'
    pdf = folder / 'figure.pdf'
    if old.exists() and pdf.exists():
        saved = json.loads(old.read_text())
        if saved.get('inputSha256') == digest and saved.get('pdfSha256') == hashlib.sha256(pdf.read_bytes()).hexdigest():
            return saved
    (folder / 'figure.tex').write_text(item['document'])
    (folder / 'question.tex').write_text(item['question'])
    try:
        run = subprocess.run(['xelatex', '-no-shell-escape', '-interaction=nonstopmode', '-halt-on-error', '-file-line-error', 'figure.tex'], cwd=folder, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, timeout=45)
        (folder / 'compile-output.txt').write_bytes(run.stdout)
        success = run.returncode == 0 and pdf.exists() and pdf.read_bytes().startswith(b'%PDF-')
        result = {'index': index, 'success': success, 'exitCode': run.returncode, 'inputSha256': digest}
        if success:
            result['pdfSha256'] = hashlib.sha256(pdf.read_bytes()).hexdigest()
        else:
            if pdf.exists(): pdf.unlink()
            result['errorTail'] = run.stdout.decode(errors='replace')[-2400:]
    except subprocess.TimeoutExpired:
        if pdf.exists(): pdf.unlink()
        result = {'index': index, 'success': False, 'inputSha256': digest, 'errorTail': 'Compile timeout after 45 seconds'}
    old.write_text(json.dumps(result, ensure_ascii=False, indent=2))
    return result

with concurrent.futures.ThreadPoolExecutor(max_workers=args.workers) as pool:
    results = list(pool.map(compile_one, enumerate(items, 1)))
report = {'engine': engine, 'total': len(results), 'successCount': sum(r['success'] for r in results), 'failures': [r['index'] for r in results if not r['success']], 'results': results}
(output / 'corpus-report.json').write_text(json.dumps(report, ensure_ascii=False, indent=2))
print(json.dumps({key: report[key] for key in ['total', 'successCount', 'failures']}, ensure_ascii=False))
